<section class="so-history mt-4" id="sales-order-history" aria-labelledby="so-history-title">
<div class="so-history-heading"><div><h2 class="h5 mb-1" id="so-history-title"><i class="bi bi-clock-history me-2" aria-hidden="true"></i>Histórico de encomendas <span class="so-count"><?=(int)$list['total']?></span></h2><p class="small text-secondary mb-0">Acompanhe a produção e as entregas. Expanda uma encomenda para consultar os artigos e as atividades.</p></div><div class="so-history-tools" data-history-tools hidden><button class="btn btn-sm btn-outline-secondary" type="button" data-expand-orders><i class="bi bi-arrows-expand me-1" aria-hidden="true"></i>Expandir todas</button><button class="btn btn-sm btn-outline-secondary" type="button" data-collapse-orders><i class="bi bi-arrows-collapse me-1" aria-hidden="true"></i>Recolher</button></div></div>
<div class="card mb-3"><div class="card-body"><form method="get" class="so-history-filters"><input type="hidden" name="page" value="sales_orders"><?php if($editing):?><input type="hidden" name="new" value="1"><?php endif;?>
<?php foreach(['customer','article'] as $key):if($filters[$key]):?><input type="hidden" name="<?=h($key)?>" value="<?=(int)$filters[$key]?>"><?php endif;endforeach;?>
<div class="so-history-search"><label class="form-label small" for="so-q">Encomenda, cliente ou artigo</label><input class="form-control form-control-sm" id="so-q" name="q" placeholder="Pesquisar no histórico…" value="<?=h($filters['q'])?>"></div>
<div><label class="form-label small" for="filter-status">Estado comercial</label><select class="form-select form-select-sm" id="filter-status" name="status"><option value="">Todos</option><?php $states=$service->all('SELECT DISTINCT status FROM erp_sales_orders ORDER BY status');$states=array_unique(array_merge(SalesOrderService::statuses(),array_column($states,'status')));foreach($states as $state):?><option <?=$filters['status']===$state?'selected':''?>><?=h($state)?></option><?php endforeach;?></select></div>
<?php foreach(['from'=>'Desde','to'=>'Até'] as $key=>$label):?><div><label class="form-label small" for="so-<?=$key?>"><?=h($label)?></label><input class="form-control form-control-sm" id="so-<?=$key?>" type="date" name="<?=$key?>" value="<?=h($filters[$key])?>"></div><?php endforeach;?>
<div><label class="form-label small" for="so-sort">Ordenar por</label><select class="form-select form-select-sm" id="so-sort" name="sort"><?php foreach(['date'=>'Data','expected'=>'Entrega prevista','number'=>'Número','customer'=>'Cliente','status'=>'Estado','source'=>'Origem'] as $key=>$label):?><option value="<?=h($key)?>" <?=$filters['sort']===$key?'selected':''?>><?=h($label)?></option><?php endforeach;?></select><input type="hidden" name="dir" value="<?=h($filters['dir'])?>"></div>
<div class="so-filter-submit"><label class="form-check small"><input class="form-check-input" type="checkbox" name="late" value="1" <?=$filters['late']==='1'?'checked':''?>> Em atraso</label><button class="btn btn-sm btn-primary" type="submit"><i class="bi bi-funnel me-1" aria-hidden="true"></i>Filtrar</button></div>
</form></div></div>
<div class="so-history-list">
<?php foreach($list['rows'] as $record):
$historyLines=$service->lines((int)$record['id']);$historyOfs=$service->workOrders((int)$record['id']);$events=$service->history((int)$record['id']);$progress=SalesOrderProgress::summary($historyLines,$historyOfs);
$cancelled=$record['status']==='Cancelada';$statusClass=$cancelled?'so-state-cancelled':($record['status']==='Concluída'?'so-state-complete':($record['status']==='Rascunho'?'so-state-draft':'so-state-active'));
?>
<details class="so-history-item" data-order-history data-order-id="<?=(int)$record['id']?>" id="so-history-<?=(int)$record['id']?>">
<summary class="so-order-summary"><div class="so-order-identity"><div class="so-order-title"><strong><?=h($record['order_number'])?></strong><span class="so-state <?=h($statusClass)?>"><?=h($record['status'])?></span></div><div class="so-order-customer"><?=h($record['customer_code'].' — '.$record['customer_name'])?></div><div class="so-order-meta"><span><i class="bi bi-calendar3" aria-hidden="true"></i><?=h(so_date($record['order_date']))?></span><span><i class="bi bi-truck" aria-hidden="true"></i>Entrega: <?=h(so_date($record['expected_date']))?></span><span><?=(int)$record['article_count']?> artigos · <?=count($historyOfs)?> OF</span><?php if($record['customer_reference']):?><span>Ref. <?=h($record['customer_reference'])?></span><?php endif;?></div></div>
<div class="so-order-progress" title="Média do progresso de cada linha, sem somar unidades diferentes."><?php foreach(['produced'=>['Produção','bi-gear','production'],'delivered'=>['Entrega','bi-truck','delivery']] as $field=>$meter):?><div class="so-meter"><div class="so-meter-label"><span><i class="bi <?=h($meter[1])?> me-1" aria-hidden="true"></i><?=h($meter[0])?></span><strong><?=h(so_number($progress[$field],0))?>%</strong></div><progress class="so-progress so-progress-<?=h($meter[2])?>" max="100" value="<?=h((string)$progress[$field])?>" aria-label="<?=h($meter[0].' da encomenda '.$record['order_number'])?>"></progress><span class="so-meter-state"><?=h($progress[$field==='produced'?'production_state':'delivery_state'])?></span></div><?php endforeach;?></div><i class="bi bi-chevron-down so-order-chevron" aria-hidden="true"></i></summary>
<div class="so-order-body">
<div class="so-order-actions"><span class="small text-secondary"><?=h($record['source_system'])?> · Resumo: média do progresso por linha.</span><div class="d-flex flex-wrap gap-2"><a class="btn btn-sm btn-outline-primary" href="<?=h(so_url(['id'=>$record['id']]))?>"><i class="bi bi-box-arrow-up-right me-1" aria-hidden="true"></i>Abrir ficha</a><a class="btn btn-sm btn-outline-secondary" href="<?=h(so_url(['id'=>$record['id'],'tab'=>'ofs']))?>"><i class="bi bi-clipboard2-check me-1" aria-hidden="true"></i>Ordens de fabrico</a></div></div>
<h3 class="h6 mb-3">Artigos e evolução</h3><div class="so-order-lines">
<?php foreach($historyLines as $historyLine):$lineProgress=SalesOrderProgress::line($historyLine);$lineOfs=array_filter($historyOfs,function($of)use($historyLine){return (int)$of['sales_order_line_id']===(int)$historyLine['id'];});$lineState=SalesOrderProgress::summary([$historyLine],$lineOfs);?>
<article class="so-evolution-line"><div class="so-line-title"><a href="erp.php?page=article_profile&amp;id=<?=(int)$historyLine['finished_product_id']?>"><?=h($historyLine['article_code'])?></a><span><?=h($historyLine['description'])?></span></div>
<div class="so-line-quantities"><?php foreach(['quantity'=>'Encomendada','planned'=>'Planeada','produced'=>'Produzida','delivered'=>'Entregue','pending'=>'Por entregar'] as $field=>$label):?><div><span><?=h($label)?></span><strong><?=h(so_number($historyLine[$field]))?></strong><small><?=h($historyLine['unit_code']?:'Unidade não registada')?></small></div><?php endforeach;?></div>
<div class="so-line-states"><span class="so-state so-state-neutral"><i class="bi bi-gear me-1" aria-hidden="true"></i><?=h($lineState['production_state'])?></span><span class="so-state so-state-neutral"><i class="bi bi-truck me-1" aria-hidden="true"></i><?=h($historyLine['logistic_state'])?></span><span class="small text-secondary">Entrega prevista: <?=h(so_date($historyLine['expected_date']?:$record['expected_date']))?></span></div>
<div class="so-line-meters"><?php foreach(['produced'=>'Produção','delivered'=>'Entrega'] as $field=>$label):?><div class="so-meter"><div class="so-meter-label"><span><?=h($label)?></span><strong><?=h(so_number($lineProgress[$field],0))?>%</strong></div><progress class="so-progress so-progress-<?=$field==='produced'?'production':'delivery'?>" max="100" value="<?=h((string)$lineProgress[$field])?>" aria-label="<?=h($label.' do artigo '.$historyLine['article_code'])?>"></progress></div><?php endforeach;?></div>
<?php if($lineOfs):?><div class="so-linked-ofs"><?php foreach($lineOfs as $historyOf):?><a href="production_dossier.php?id=<?=(int)$historyOf['id']?>"><i class="bi bi-clipboard2-check me-1" aria-hidden="true"></i><?=h($historyOf['order_number'])?> <span><?=h($historyOf['status'])?></span></a><?php endforeach;?></div><?php else:?><p class="small text-secondary mb-0 mt-2">Sem OF associadas a este artigo.</p><?php endif;?></article>
<?php endforeach;?>
</div>
<div class="so-activity"><h3 class="h6"><i class="bi bi-clock-history me-2" aria-hidden="true"></i>Histórico de atividades</h3><?php if(!$events):?><p class="small text-secondary mb-0">Sem atividades registadas.</p><?php else:?><ol class="so-timeline"><?php foreach($events as $event):$before=json_decode($event['old_values_json'],true)?:[];$after=json_decode($event['new_values_json'],true)?:[];$eventLabel=['refresh_confirmation'=>'Confirmação atualizada','issue_confirmation'=>'Confirmação emitida','create'=>'Encomenda criada','update'=>'Encomenda atualizada','link_work_order'=>'OF associada','link_delivery'=>'Entrega associada'][$event['action']]??'Alteração registada';$eventTime=strtotime($event['created_at']);?><li><time><?=h($eventTime?date('d/m/Y H:i',$eventTime):$event['created_at'])?></time><div><strong><?=h($eventLabel)?></strong><?php if(isset($after['order']['status'])):?><span><?=h(($before['order']['status']??'Nova').' → '.$after['order']['status'])?></span><?php endif;?></div></li><?php endforeach;?></ol><?php endif;?></div>
</div></details>
<?php endforeach;?>
<?php if(!$list['rows']):?><div class="so-history-empty"><i class="bi bi-inbox" aria-hidden="true"></i><h3 class="h6 mt-3">Sem encomendas para os filtros selecionados</h3><p class="small text-secondary mb-0">As encomendas guardadas aparecerão aqui com a evolução dos seus artigos.</p></div><?php endif;?></div>
<nav aria-label="Paginação do histórico" class="so-history-pagination"><span><?=(int)$list['total']?> encomendas · página <?=(int)$list['page']?> / <?=(int)$list['pages']?></span><div class="d-flex gap-2"><?php foreach(['Anterior'=>-1,'Seguinte'=>1] as $label=>$delta):$page=$list['page']+$delta;if($page<1||$page>$list['pages'])continue;$pageFilters=array_merge($filters,['p'=>$page]);if($editing)$pageFilters['new']=1;?><a class="btn btn-sm btn-outline-secondary" href="<?=h(so_url($pageFilters))?>#sales-order-history"><i class="bi <?=$delta<0?'bi-chevron-left':'bi-chevron-right'?> me-1" aria-hidden="true"></i><?=h($label)?></a><?php endforeach;?></div></nav>
</section>
